1 Reis 1 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Quem foi trazida para cuidar do rei Davi na velhice?","o":["Abisague, a sunamita","Bate-Seba","Hagite","Mical"],"c":0,"v":3,"e":"No versículo 3, os servos procuraram por todo Israel e trouxeram Abisague, a sunamita, ao rei."},
 {"t":"multipla","p":"Quem se aliou a Adonias e o ajudava?","o":["Zadoque e Benaia","Joabe e Abiatar","Natã e Simei","Salomão e Reí"],"c":1,"v":7,"e":"O versículo 7 diz que Adonias se aliou a Joabe, filho de Zeruia, e a Abiatar, o sacerdote."},
 {"t":"multipla","p":"Quem aconselhou Bate-Seba a ir falar com o rei Davi?","o":["Zadoque, o sacerdote","Benaia, filho de Joiada","Natã, o profeta","Abisague, a sunamita"],"c":2,"v":12,"e":"Nos versículos 11 e 12, Natã fala com Bate-Seba e oferece a ela um conselho para salvar sua vida e a de Salomão."},
 {"t":"multipla","p":"Davi mandou levar Salomão até Giom montado em quê?","o":["Num cavalo de Adonias","Num carro de guerra","Num jumento emprestado","Na mula do rei Davi"],"c":3,"v":33,"e":"No versículo 33, Davi manda que Salomão seja montado na mula do rei e levado até Giom."},
 {"t":"multipla","p":"De onde Zadoque tirou o chifre do azeite para ungir Salomão?","o":["Do tabernáculo","Da casa de Natã","Da fonte de Rogel","Do palácio de Adonias"],"c":0,"v":39,"e":"O versículo 39 diz que Zadoque retirou do tabernáculo o chifre do azeite e ungiu Salomão."},
 {"t":"cv","p":"Jônatas, filho de Abiatar, contou a Adonias que o rei Davi havia declarado Salomão rei.","c":true,"v":43,"e":"No versículo 43, Jônatas responde a Adonias que o rei Davi declarou Salomão como rei."},
 {"t":"cv","p":"Depois da notícia, os convidados de Adonias ficaram ao lado dele para defendê-lo.","c":false,"v":49,"e":"O versículo 49 diz que os convidados estremeceram e cada um seguiu seu próprio caminho."},
 {"t":"cv","p":"Depois que Adonias se prostrou diante dele, Salomão o mandou para sua casa.","c":true,"v":53,"e":"No versículo 53, Adonias se prostra diante do rei, e Salomão lhe diz: Vá para a sua casa."}
]}

1 Reis 7 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Qual era o outro nome da Sala do Trono, onde Salomão julgava?","o":["Salão das Colunas","Sala do Julgamento","Casa do bosque do Líbano","Santo dos Santos"],"c":1,"v":7,"e":"O versículo 7 diz que a Sala do Trono, onde Salomão julgava, era a Sala do Julgamento."},
 {"t":"multipla","p":"Para quem Salomão construiu uma casa semelhante à Sala do Trono?","o":["Para Hirão de Tiro","Para a rainha de Sabá","Para a filha de Faraó, sua esposa","Para Davi, seu pai"],"c":2,"v":8,"e":"O versículo 8 diz que Salomão construiu uma casa semelhante à Sala do Trono para a filha de Faraó, que ele tinha tomado como esposa."},
 {"t":"multipla","p":"Em que tipo de obra Hirão de Tiro era cheio de sabedoria e entendimento?","o":["Obra em bronze","Obra em cedro","Obra em pedra","Obra em tecido"],"c":0,"v":14,"e":"O versículo 14 diz que Hirão era cheio de sabedoria e entendimento para realizar toda obra em bronze."},
 {"t":"multipla","p":"Que nomes foram dados às duas colunas levantadas no pórtico do templo?","o":["Sucote e Zaretã","Tiro e Naftali","Sião e Moriá","Jaquim e Boaz"],"c":3,"v":21,"e":"O versículo 21 diz que a coluna da direita se chamou Jaquim e a da esquerda, Boaz."},
 {"t":"multipla","p":"Sobre o que se assentava o mar de fundição?","o":["Sobre doze leões","Sobre doze bois","Sobre quatro rodas de bronze","Sobre dez suportes"],"c":1,"v":25,"e":"O versículo 25 diz que o mar se assentava sobre doze bois, três voltados para cada direção."},
 {"t":"cv","p":"Sobre cada uma das dez bases havia uma pia de bronze.","c":true,"v":38,"e":"O versículo 38 diz que Hirão fez dez pias de bronze e que sobre cada uma das dez bases havia uma pia."},
 {"t":"cv","p":"Salomão pesou com cuidado todo o bronze usado nos utensílios.","c":false,"v":47,"e":"O versículo 47 diz que Salomão não pesou os utensílios porque eram numerosos demais, e por isso o peso do bronze não foi apurado."},
 {"t":"cv","p":"Ao terminar a obra, Salomão colocou entre os tesouros da Casa do Senhor as coisas que Davi, seu pai, tinha dedicado.","c":true,"v":51,"e":"O versículo 51 diz que Salomão trouxe a prata, o ouro e os utensílios dedicados por Davi e os colocou entre os tesouros da Casa do Senhor."}
]}

1 Reis 4 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Quem era o comandante do exército de Salomão?","o":["Benaia, filho de Joiada","Adoniram, filho de Abda","Zabude, filho de Natã","Josafá, filho de Ailude"],"c":0,"v":4,"e":"O versículo 4 diz que Benaia, filho de Joiada, era comandante do exército."},
 {"t":"multipla","p":"Como os doze intendentes dividiam o sustento do rei e da sua casa?","o":["Todos juntos, uma vez por ano","Cada um durante uma semana","Cada um durante um mês do ano","Só nos tempos de festa"],"c":2,"v":7,"e":"O versículo 7 diz que cada intendente era responsável por suprir o rei durante um mês do ano."},
 {"t":"multipla","p":"Com quem Ben-Abinadabe, que governava a região de Dor, era casado?","o":["Basemate","Tafate, filha de Salomão","Abisague","Mical"],"c":1,"v":11,"e":"O versículo 11 diz que Ben-Abinadabe era casado com Tafate, filha de Salomão."},
 {"t":"multipla","p":"Como Judá e Israel viviam nos dias de Salomão?","o":["Em tendas, sempre prontos para a guerra","Em cidades muradas, com medo dos vizinhos","Espalhados entre outros povos","Seguros, cada um debaixo da sua videira e da sua figueira"],"c":3,"v":25,"e":"O versículo 25 diz que habitavam seguros, cada um debaixo da sua videira e da sua figueira, de Dã até Berseba."},
 {"t":"multipla","p":"A sabedoria de Salomão era maior que a de todos os do Oriente e que toda a sabedoria de qual povo?","o":["Dos filisteus","Dos fenícios","Dos egípcios","Dos gregos"],"c":2,"v":30,"e":"O versículo 30 compara a sabedoria de Salomão com a de todos os do Oriente e com toda a sabedoria dos egípcios."},
 {"t":"cv","p":"Os reinos dominados por Salomão pagavam tributo e o serviram durante todos os dias da sua vida.","c":true,"v":21,"e":"O versículo 21 diz que esses reinos pagavam tributo e serviram a Salomão todos os dias da sua vida."},
 {"t":"cv","p":"Os provedores às vezes deixavam faltar mantimentos à mesa do rei.","c":false,"v":27,"e":"O versículo 27 diz que cada provedor fornecia no seu mês e que não deixavam faltar coisa alguma."},
 {"t":"cv","p":"Salomão falou sobre as plantas, desde o cedro do Líbano até o hissopo que brota da parede.","c":true,"v":33,"e":"O versículo 33 diz que Salomão discorreu sobre as plantas, do cedro do Líbano ao hissopo da parede."}
]}

1 Reis 13 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Qual nome o homem de Deus anunciou para o filho que nasceria à casa de Davi?","o":["Ezequias","Joás","Josias","Asa"],"c":2,"v":2,"e":"No clamor contra o altar, o homem de Deus diz que o filho da casa de Davi se chamará Josias."},
 {"t":"multipla","p":"O que aconteceu com a mão que Jeroboão estendeu contra o homem de Deus?","o":["Secou, e ele não pôde recolhê-la","Ficou coberta de lepra","Foi queimada pelo fogo do altar","Tremeu, e ele deixou cair o incenso"],"c":0,"v":4,"e":"O texto diz que a mão do rei secou e ele não pôde recolhê-la."},
 {"t":"multipla","p":"Além de não comer pão nem beber água, o que mais o Senhor ordenou ao homem de Deus?","o":["Não falar com o rei de Israel","Não entrar no templo de Betel","Não aceitar nenhum presente","Não voltar pelo caminho por onde foi"],"c":3,"v":9,"e":"Ao recusar o convite do rei, o homem de Deus explica que o Senhor também mandou não voltar pelo mesmo caminho."},
 {"t":"multipla","p":"O que o profeta idoso disse para convencer o homem de Deus a voltar com ele?","o":["Que o rei tinha mandado chamá-lo","Que um anjo lhe falara por ordem do Senhor","Que havia um leão no caminho","Que seus filhos estavam doentes"],"c":1,"v":18,"e":"O profeta idoso diz que um anjo lhe falou por ordem do Senhor, mas o texto avisa que ele estava mentindo."},
 {"t":"multipla","p":"Depois de sepultar o homem de Deus, o que o profeta idoso pediu a seus filhos?","o":["Que destruíssem o altar de Betel","Que fossem morar em Judá","Que o sepultassem junto aos ossos do homem de Deus","Que matassem o leão"],"c":2,"v":31,"e":"O profeta idoso pede que, quando morrer, o enterrem no túmulo do homem de Deus, com os ossos junto aos dele."},
 {"t":"cv","p":"O homem de Deus aceitou ir à casa do rei para se refrescar e receber recompensa.","c":false,"v":8,"e":"Ele respondeu que não iria nem com a metade da casa do rei, e que não comeria nem beberia ali."},
 {"t":"cv","p":"Quando o profeta idoso encontrou o corpo, o leão não tinha devorado o corpo nem despedaçado o jumento.","c":true,"v":28,"e":"O texto diz que o jumento e o leão estavam parados ao lado do cadáver e que o leão não devorou o corpo nem despedaçou o jumento."},
 {"t":"cv","p":"Depois desses acontecimentos, Jeroboão abandonou seu mau caminho.","c":false,"v":33,"e":"O capítulo diz que Jeroboão não se apartou do seu mau caminho e continuou consagrando quem quisesse como sacerdote dos altos."}
]}

1 Reis 8 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"De onde Salomão mandou trazer a arca da Aliança para o templo?","o":["Da Cidade de Davi, que é Sião","De Siló","De Hebrom","De Betel"],"c":0,"v":1,"e":"No começo do capítulo, Salomão reúne os líderes para fazer subir a arca da Cidade de Davi, que é Sião, para o templo."},
 {"t":"multipla","p":"O que havia dentro da arca?","o":["Só as duas tábuas de pedra","As tábuas, o maná e a vara de Arão","Os utensílios sagrados do tabernáculo","Nada, a arca estava vazia"],"c":0,"v":9,"e":"O texto diz que na arca não havia nada além das duas tábuas de pedra que Moisés pôs ali junto a Horebe."},
 {"t":"multipla","p":"Por que os sacerdotes não puderam ficar em pé para ministrar?","o":["Por causa da nuvem que encheu a Casa do SENHOR","Porque Salomão mandou que saíssem","Porque o fogo desceu sobre o altar","Porque a casa ficou cheia de gente"],"c":0,"v":11,"e":"Quando os sacerdotes saíram do santuário, uma nuvem encheu a casa, e eles não puderam ministrar porque a glória do SENHOR a enchia."},
 {"t":"multipla","p":"Segundo Salomão, o que o Senhor disse a Davi sobre construir a casa?","o":["Que Davi fez bem em querer, mas seu filho a edificaria","Que Davi não era digno de pensar nisso","Que Davi devia construí-la junto com o filho","Que a casa não seria necessária"],"c":0,"v":19,"e":"Salomão conta que o Senhor elogiou a intenção de Davi, mas disse que o filho dele é quem edificaria a casa."},
 {"t":"multipla","p":"Na oração, Salomão pede que Deus ouça também quem?","o":["O estrangeiro que vier de terras distantes","Apenas os sacerdotes e levitas","Somente os reis de Israel","Os anjos que servem no céu"],"c":0,"v":41,"e":"Salomão pede que Deus ouça também o estrangeiro que não é de Israel e vem de terras distantes por amor do seu nome."},
 {"t":"cv","p":"Salomão reconhece que nem o céu dos céus pode conter Deus, quanto menos a casa que ele edificou.","c":true,"v":27,"e":"No meio da oração, Salomão pergunta se Deus habitará na terra e diz que nem os céus podem contê-lo."},
 {"t":"cv","p":"Na oração, Salomão diz que existem homens que nunca pecam.","c":false,"v":46,"e":"Ao falar do cativeiro, Salomão diz o contrário: \"não há homem que não peque\"."},
 {"t":"cv","p":"Salomão consagrou o meio do átrio porque o altar de bronze era pequeno demais para tantas ofertas.","c":true,"v":64,"e":"Perto do fim do capítulo, o texto explica que o altar de bronze não comportava os holocaustos, as ofertas de manjares e a gordura."}
]}

1 Reis 9 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Onde o Senhor já tinha aparecido a Salomão antes desta vez?","o":["Em Gibeão","Em Betel","Em Siló","Em Hebrom"],"c":0,"v":2,"e":"O versículo 2 diz que o Senhor apareceu de novo a Salomão, como lhe havia aparecido em Gibeão."},
 {"t":"multipla","p":"Deus pediu que Salomão caminhasse diante dele como quem?","o":["Moisés","Abraão","Davi, seu pai","Samuel"],"c":2,"v":4,"e":"No versículo 4, Deus pede que Salomão caminhe diante dele como Davi, seu pai, com integridade de coração."},
 {"t":"multipla","p":"O que Deus disse que faria se Israel servisse a outros deuses?","o":["Tiraria a sabedoria de Salomão","Entregaria Jerusalém a Hirão","Daria o templo ao Egito","Eliminaria Israel da terra que lhe deu"],"c":3,"v":7,"e":"O versículo 7 diz que Deus eliminaria Israel da terra que lhe deu e lançaria a casa longe da sua presença."},
 {"t":"multipla","p":"Como Hirão reagiu ao ver as cidades que Salomão lhe deu na Galileia?","o":["Gostou e agradeceu","Não gostou delas","Devolveu-as a Salomão","Foi morar nelas"],"c":1,"v":12,"e":"O versículo 12 diz que Hirão foi ver as cidades, mas elas não lhe agradaram."},
 {"t":"multipla","p":"Quem tomou Gezer e a deu como dote à esposa de Salomão?","o":["Hirão, rei de Tiro","O rei de Edom","Faraó, rei do Egito","Os jebuseus"],"c":2,"v":16,"e":"O versículo 16 conta que Faraó tomou e queimou Gezer e a deu como dote à sua filha, esposa de Salomão."},
 {"t":"cv","p":"Salomão fez dos filhos de Israel trabalhadores escravos.","c":false,"v":22,"e":"O versículo 22 diz que Salomão não fez escravo nenhum dos filhos de Israel; eles eram homens de guerra, oficiais e chefes."},
 {"t":"cv","p":"Salomão oferecia holocaustos e sacrifícios pacíficos três vezes por ano no altar que edificou ao Senhor.","c":true,"v":25,"e":"O versículo 25 diz que Salomão oferecia, três vezes por ano, holocaustos e sacrifícios pacíficos sobre o altar."},
 {"t":"cv","p":"As embarcações chegaram a Ofir e trouxeram prata ao rei Salomão.","c":false,"v":28,"e":"O versículo 28 diz que de Ofir trouxeram ouro, e não prata, ao rei Salomão."}
]}

1 Reis 14 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Para onde Jeroboão mandou a mulher dele consultar o profeta?","o":["Betel","Siló","Jerusalém","Tirza"],"c":1,"v":2,"e":"No versículo 2, Jeroboão manda a mulher ir a Siló, onde estava o profeta Ahias."},
 {"t":"multipla","p":"Por que Ahias não conseguia ver a mulher de Jeroboão?","o":["Ele estava dormindo","Ela estava com o rosto coberto","Os olhos dele estavam obscurecidos pela velhice","A casa estava escura"],"c":2,"v":4,"e":"O versículo 4 diz que os olhos de Ahias estavam obscurecidos em razão da velhice."},
 {"t":"multipla","p":"Quem avisou Ahias de que a mulher de Jeroboão estava chegando?","o":["Um servo de Ahias","A própria mulher","Um mensageiro de Jeroboão","O SENHOR"],"c":3,"v":5,"e":"No versículo 5, o SENHOR avisa Ahias de que a mulher de Jeroboão viria consultá-lo sobre o filho."},
 {"t":"multipla","p":"Segundo Ahias, o que aconteceria quando os pés da mulher entrassem na cidade?","o":["O menino morreria","O menino ficaria curado","Jeroboão morreria","O rei iria até o profeta"],"c":0,"v":12,"e":"No versículo 12, Ahias diz que, quando os pés dela entrassem na cidade, o menino morreria."},
 {"t":"multipla","p":"Por que somente o menino teria sepultura entre os da casa de Jeroboão?","o":["Porque era o filho mais velho","Porque se achou nele coisa boa diante do Senhor","Porque a mãe pediu isso ao profeta","Porque morreu em Siló"],"c":1,"v":13,"e":"O versículo 13 explica que se achou nele coisa boa diante do Senhor, Deus de Israel."},
 {"t":"cv","p":"O menino morreu quando a mãe chegou ao limiar da casa, em Tirza.","c":true,"v":17,"e":"O versículo 17 diz que, ao ela alcançar o limiar da casa em Tirza, o menino morreu."},
 {"t":"cv","p":"Depois de Jeroboão, seu filho Nadabe assumiu o trono.","c":true,"v":20,"e":"O versículo 20 diz que Nadabe, filho de Jeroboão, assumiu o seu lugar no trono."},
 {"t":"cv","p":"Roboão substituiu os escudos de ouro levados por Sisaque por escudos de prata.","c":false,"v":27,"e":"O versículo 27 diz que Roboão fez escudos de bronze no lugar dos de ouro."}
]}

1 Reis 11 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Em que fase da vida as mulheres de Salomão desviaram o coração dele para outros deuses?","o":["Na velhice","No início do reinado","Logo depois de ser ungido rei","Ainda na juventude, antes de reinar"],"c":0,"v":4,"e":"O versículo 4 diz que foi na velhice de Salomão que suas mulheres lhe desviaram o coração."},
 {"t":"multipla","p":"Por que o Senhor disse que não tiraria o reino nos dias do próprio Salomão?","o":["Por amor de Davi, pai de Salomão","Porque Salomão se arrependeu","Porque o profeta Aías intercedeu","Porque Salomão derrubou os santuários"],"c":0,"v":12,"e":"No versículo 12 o Senhor diz que não o faria nos dias de Salomão por amor de Davi, seu pai."},
 {"t":"multipla","p":"Qual adversário de Salomão pertencia à linhagem real de Edom?","o":["Hadade","Rezom","Jeroboão","Hadadezer"],"c":0,"v":14,"e":"O versículo 14 apresenta Hadade, o edomita, da linhagem real de Edom."},
 {"t":"multipla","p":"O que o profeta Aías fez com o manto novo ao encontrar Jeroboão no campo?","o":["Rasgou-o em doze pedaços","Colocou-o sobre os ombros de Jeroboão","Queimou-o diante dele","Deixou-o no caminho"],"c":0,"v":30,"e":"O versículo 30 diz que Aías tomou o manto novo que vestia e o rasgou em doze pedaços."},
 {"t":"multipla","p":"Para onde Jeroboão fugiu quando Salomão procurou matá-lo?","o":["Para o Egito","Para Damasco","Para Edom","Para Moabe"],"c":0,"v":40,"e":"O versículo 40 diz que Jeroboão fugiu para o Egito, para Sisaque, e ficou lá até a morte de Salomão."},
 {"t":"cv","p":"Hadade pediu a Faraó para voltar à sua terra depois de ouvir que Davi e Joabe tinham morrido.","c":true,"v":21,"e":"No versículo 21, ao saber da morte de Davi e de Joabe, Hadade pediu a Faraó para voltar à sua terra."},
 {"t":"cv","p":"Jeroboão, filho de Nebate, era da tribo de Judá.","c":false,"v":26,"e":"O versículo 26 diz que Jeroboão era efraimita, da cidade de Zereda."},
 {"t":"cv","p":"Depois da morte de Salomão, Jeroboão reinou em seu lugar.","c":false,"v":43,"e":"O versículo 43 diz que quem reinou no lugar de Salomão foi Roboão, seu filho."}
]}

1 Reis 3 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Com quem Salomão se casou no começo do capítulo?","o":["Com a filha de Faraó, rei do Egito","Com a filha do rei de Tiro","Com uma moça de Gibeão","Com a filha de um sacerdote de Jerusalém"],"c":0,"v":1,"e":"O versículo 1 diz que Salomão fez aliança com Faraó e tomou por esposa a filha dele."},
 {"t":"multipla","p":"Onde o Senhor apareceu a Salomão em sonho?","o":["Em Jerusalém","Em Gibeão","Em Betel","Em Hebrom"],"c":1,"v":5,"e":"O versículo 5 diz que foi em Gibeão, durante a noite, em sonhos, que o Senhor apareceu a Salomão."},
 {"t":"multipla","p":"O que Salomão pediu a Deus?","o":["Vida longa","Riquezas e glória","Um coração compreensivo para julgar o povo","A morte de seus inimigos"],"c":2,"v":9,"e":"No versículo 9 Salomão pede um coração compreensivo para julgar o povo e discernir entre o bem e o mal."},
 {"t":"multipla","p":"Além do que Salomão pediu, o que Deus também lhe deu?","o":["Vitória sobre o Egito","Riquezas e glória","Um exército numeroso","O templo já construído"],"c":1,"v":13,"e":"No versículo 13 Deus diz que lhe deu também o que não pediu: riquezas e glória."},
 {"t":"multipla","p":"Segundo a primeira mulher, como morreu o filho da outra?","o":["De doença, durante a noite","Caiu da cama","A mãe se deitou sobre ele","Nasceu sem vida"],"c":2,"v":19,"e":"O versículo 19 diz que o filho morreu durante a noite porque a mãe se deitou sobre ele."},
 {"t":"cv","p":"Salomão mandou cortar o menino vivo ao meio e dar metade a cada mulher.","c":true,"v":25,"e":"No versículo 25 o rei ordena que o menino vivo seja cortado ao meio e dividido entre as duas."},
 {"t":"cv","p":"A mãe do menino vivo concordou que a criança fosse dividida.","c":false,"v":26,"e":"No versículo 26 a mãe verdadeira pede que deem o menino à outra e não o matem, e foi a outra que disse para dividi-lo."},
 {"t":"cv","p":"Todo o Israel respeitou o rei porque percebeu que havia nele a sabedoria de Deus para fazer justiça.","c":true,"v":28,"e":"O versículo 28 diz que Israel ouviu a sentença e teve profundo respeito pelo rei por ver nele a sabedoria de Deus."}
]}

1 Reis 5 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Por que Hirão, rei de Tiro, enviou seus servos a Salomão?","o":["Soube que Salomão fora ungido rei no lugar de Davi","Queria pedir ajuda numa guerra","Queria vender madeira de cedro","Foi chamado para a dedicação do templo"],"c":0,"v":1,"e":"O versículo 1 diz que Hirão soube que haviam ungido Salomão rei no lugar de seu pai e que sempre fora amigo de Davi."},
 {"t":"multipla","p":"Segundo Salomão, por que Davi não pôde edificar a casa ao nome do Senhor?","o":["Porque não tinha madeira suficiente","Por causa das guerras que o envolveram","Porque Hirão não quis ajudar","Porque morreu antes de começar"],"c":1,"v":3,"e":"No versículo 3, Salomão explica que Davi não pôde edificar a casa por causa das guerras que o envolveram."},
 {"t":"multipla","p":"Por que Salomão pediu que os servos de Hirão cortassem os cedros?","o":["Porque Israel não tinha ferramentas","Porque os cedros eram de Hirão e só ele podia cortá-los","Porque entre o povo de Salomão ninguém cortava madeira como os sidônios","Porque os israelitas estavam em guerra"],"c":2,"v":6,"e":"No versículo 6, Salomão diz que entre o seu povo não havia quem cortasse madeira como os sidônios."},
 {"t":"multipla","p":"Como Hirão disse que levaria a madeira até o lugar indicado por Salomão?","o":["Em carros puxados por bois","Nas costas dos carregadores","Em navios de Társis","Em jangadas pelo mar"],"c":3,"v":9,"e":"No versículo 9, Hirão diz que levaria a madeira do Líbano até o mar e a transportaria em jangadas."},
